</style></head><body><header class="top"><a class="brand" href="{{ route('dashboard') }}"><span>✳</span> RuangKerja <span style="color:#a2adbd">KP2MI</span></a><a class="back" href="{{ route('dashboard') }}">← Kembali ke dashboard</a></header><main class="wrap"><div class="heading"><div><div class="eyebrow">PENGELOLAAN AKSES</div><h1>Pengguna workspace</h1><p>Buat akun dan tetapkan peran untuk mengatur akses dashboard.</p></div></div><div class="grid"><section class="panel"><h2>Tambah pengguna</h2><p class="hint">Kata sandi disimpan dalam bentuk hash di database.</p>@if(session('status'))<div class="alert">{{ session('status') }}</div>@endif<form method="POST" action="{{ route('users.store') }}">@csrf<div class="field"><label>Nama lengkap</label><input name="name" value="{{ old('name') }}" required>@error('name')<span class="error">{{ $message }}</span>@enderror</div><div class="field"><label>Email</label><input type="email" name="email" value="{{ old('email') }}" placeholder="nama@kp2mi.go.id" required>@error('email')<span class="error">{{ $message }}</span>@enderror</div><div class="field"><label>Peran</label><select name="role" required><option value="kepegawaian">Kepegawaian · pengelola</option><option value="sesditjen">Sesditjen · pemberi persetujuan</option></select>@error('role')<span class="error">{{ $message }}</span>@enderror</div><div class="row"><div class="field"><label>Kata sandi · minimal 8 karakter</label><input type="password" name="password" required>@error('password')<span class="error">{{ $message }}</span>@enderror</div><div class="field"><label>Ulangi kata sandi</label><input type="password" name="password_confirmation" required></div></div><button class="submit" type="submit">Simpan akun</button></form></section><section class="panel"><h2>Akun terdaftar</h2><p class="hint">Akses aplikasi mengikuti peran yang ditetapkan.</p><table class="table"><thead><tr><th>Nama</th><th>Peran</th><th>Akses</th></tr></thead><tbody>@foreach($users as $user)<tr>